def idw_interpolate(lat_grid: np.ndarray, lon_grid: np.ndarray,
                    sta_lat: np.ndarray, sta_lon: np.ndarray,
                    values: np.ndarray) -> np.ndarray:
    """
    Inverse-distance-squared interpolation from N stations to a grid of cells.

    lat_grid, lon_grid  : 2-D arrays, shape (nrows, ncols)
    sta_lat, sta_lon    : 1-D arrays, shape (N,)
    values              : 1-D array, shape (N,)
    Returns             : 2-D array, shape (nrows, ncols)
    """
    # Flatten grid for broadcasting
    lat_f = lat_grid.ravel()[:, np.newaxis]      # (ncells, 1)
    lon_f = lon_grid.ravel()[:, np.newaxis]
    d2    = (lat_f - sta_lat)**2 + (lon_f - sta_lon)**2  # (ncells, N)
    d2    = np.where(d2 == 0, 1e-8, d2)
    w     = 1.0 / d2
    result = (w * values).sum(axis=1) / w.sum(axis=1)
    return result.reshape(lat_grid.shape)
